create function public.resolve_picture_caption_reveal(p_game_session_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare round_record public.picture_caption_rounds; reveal_record public.picture_caption_reveals; ballot_count integer; begin select round.* into round_record from public.picture_caption_rounds round where round.game_session_id=p_game_session_id and round.state='active' and round.phase='revealing' for update; if not found then return; end if; select * into reveal_record from public.picture_caption_reveals where round_id=round_record.id; if reveal_record.paused_at is not null then return; end if; select count(*) into ballot_count from public.picture_caption_ballots where round_id=round_record.id; if reveal_record.started_at+make_interval(secs=>ballot_count*2)<=now() then update public.picture_caption_rounds set phase='results' where id=round_record.id; update public.game_sessions set revision=revision+1 where id=p_game_session_id; end if; end; $$;
create or replace function public.set_picture_caption_paused(p_host_id uuid,p_party_id uuid,p_command_id uuid,p_expected_revision bigint,p_paused boolean) returns table(game_session_id uuid,session_revision bigint) language plpgsql security definer set search_path='' as $$ declare existing_response jsonb; session_id uuid; next_revision bigint; active_round public.picture_caption_rounds; paused_at timestamptz; begin select response into existing_response from public.command_receipts where actor_id=p_host_id and command_id=p_command_id; if found then return query select(existing_response->>'gameSessionId')::uuid,(existing_response->>'sessionRevision')::bigint; return; end if; select session.id into session_id from public.game_sessions session join public.parties party on party.current_game_session_id=session.id where party.id=p_party_id and party.host_id=p_host_id and session.state='live' and session.revision=p_expected_revision for update of session; if not found then raise exception using errcode='40001',message='stale_revision'; end if; select round.* into active_round from public.picture_caption_rounds round where round.game_session_id=session_id and round.state='active' for update; if not found then raise exception using errcode='40001',message='stale_revision'; end if; if active_round.phase='revealing' then select paused_at into paused_at from public.picture_caption_reveals where round_id=active_round.id for update; if p_paused and paused_at is null then update public.picture_caption_reveals set paused_at=now() where round_id=active_round.id; elsif not p_paused and paused_at is not null then update public.picture_caption_reveals set started_at=started_at+(now()-paused_at),paused_at=null where round_id=active_round.id; else raise exception using errcode='40001',message='stale_revision'; end if; elsif active_round.phase='captioning' then if p_paused then update public.picture_caption_rounds set paused_remaining_seconds=greatest(0,ceil(extract(epoch from captioning_deadline-now()))::integer),captioning_deadline=null where id=active_round.id and captioning_deadline is not null; else update public.picture_caption_rounds set captioning_deadline=now()+make_interval(secs=>paused_remaining_seconds),paused_remaining_seconds=null where id=active_round.id and paused_remaining_seconds is not null; end if; else if p_paused then update public.picture_caption_rounds set voting_paused_remaining_seconds=greatest(0,ceil(extract(epoch from voting_deadline-now()))::integer),voting_deadline=null where id=active_round.id and voting_deadline is not null; else update public.picture_caption_rounds set voting_deadline=now()+make_interval(secs=>voting_paused_remaining_seconds),voting_paused_remaining_seconds=null where id=active_round.id and voting_paused_remaining_seconds is not null; end if; end if; if not found then raise exception using errcode='40001',message='stale_revision'; end if; update public.game_sessions set revision=revision+1 where id=session_id returning revision into next_revision; insert into public.command_receipts values(p_host_id,p_command_id,'set_picture_caption_paused',jsonb_build_object('gameSessionId',session_id,'sessionRevision',next_revision)); return query select session_id,next_revision; end; $$;
revoke all on function public.resolve_picture_caption_reveal(uuid) from public,anon,authenticated;
grant execute on function public.resolve_picture_caption_reveal(uuid) to service_role;